import { describe, expect, it } from 'vitest'
import {
  type Glyph,
  type GlyphTable,
  measureText,
  palCharWidth,
  palWordWidth,
  renderText,
} from './font.js'
import { createFramebuffer } from './framebuffer.js'

// 可打印ASCII/CJK的菜单宽度近似；其它码点边界见font.ts。
//   PAL_CharWidth = font_width[ch]>>1(标准字体 ASCII<0x80=8 / CJK=16);PAL_WordWidth = (Σ+8)>>4。
//   **不**复用 measureText(它依赖 glyph 加载且 ASCII fallback 成 16,见 measureText)。
describe('palCharWidth / palWordWidth(sdlpal font.c:611-629 / ui.c:836-861)', () => {
  it('palCharWidth:ASCII<0x80=8,CJK=16', () => {
    expect(palCharWidth('A'.codePointAt(0)!)).toBe(8)
    expect(palCharWidth('9'.codePointAt(0)!)).toBe(8)
    expect(palCharWidth('新'.codePointAt(0)!)).toBe(16)
    expect(palCharWidth('中'.codePointAt(0)!)).toBe(16)
  })

  it("palWordWidth:'新的故事'(4 CJK)→ (64+8)>>4 = 4", () => {
    expect(palWordWidth('新的故事')).toBe(4)
  })

  it('palWordWidth:5 CJK → (80+8)>>4 = 5;6 CJK → (96+8)>>4 = 6', () => {
    expect(palWordWidth('读取上次存档')).toBe(6) // 6 CJK
    expect(palWordWidth('新新新新新')).toBe(5) // 5 CJK
  })

  it('palWordWidth:8 ASCII → (64+8)>>4 = 4(ASCII 半宽,不等于 length)', () => {
    expect(palWordWidth('NEWGAME!')).toBe(4) // 8×8=64 → 4,而非 length 8
  })
})

// ── mock GlyphTable ───────────────────────────────────────────────────
// A (U+0041): 8×16, 第 0 行全亮(0xFF)
// 中 (U+4E2D): 16×16, 第 0 行全亮(0xFF 0xFF)

const mockGlyphs: GlyphTable = {
  has: (cp: number) => cp === 65 || cp === 0x4e2d,
  get: (cp: number): Glyph | undefined => {
    if (cp === 65) {
      // 8px wide, 16 rows, bytesPerRow = 1
      const b = new Uint8Array(16)
      b[0] = 0xff // 第 0 行全亮 8 个像素
      return { width: 8, height: 16, bitmap: b }
    }
    if (cp === 0x4e2d) {
      // 16px wide, 16 rows, bytesPerRow = 2
      const b = new Uint8Array(32)
      b[0] = 0xff // 第 0 行左 8 px 全亮
      b[1] = 0xff // 第 0 行右 8 px 全亮
      return { width: 16, height: 16, bitmap: b }
    }
    return undefined
  },
}

// ── renderText ────────────────────────────────────────────────────────

describe('renderText (P4.T3)', () => {
  it('blits ASCII A: top row 8 pixels lit at fgColor', () => {
    const fb = createFramebuffer()
    renderText(fb, 'A', 0, 0, 0xff, mockGlyphs)
    // 第 0 行 8 个像素应为 0xFF(fgColor)
    for (let i = 0; i < 8; i++) {
      expect(fb.indices[i]).toBe(0xff)
    }
    // 第 0 行第 8 个像素不属于 A
    expect(fb.indices[8]).toBe(0)
  })

  it('CJK 中: top row 16 pixels lit at fgColor', () => {
    const fb = createFramebuffer()
    renderText(fb, '中', 0, 0, 0xff, mockGlyphs)
    for (let i = 0; i < 16; i++) {
      expect(fb.indices[i]).toBe(0xff)
    }
    expect(fb.indices[16]).toBe(0)
  })

  it('mixed glyph widths advance from a nonzero origin', () => {
    const fb = createFramebuffer()
    const w = renderText(fb, 'A中', 4, 8, 0xff, mockGlyphs)
    expect(w).toBe(24) // 8 + 16
    // A 的首行位于 (4,8) 起的 8 像素
    for (let i = 0; i < 8; i++) expect(fb.indices[8 * 320 + 4 + i]).toBe(0xff)
    // 中紧跟在 x=12 起的 16 像素
    for (let i = 8; i < 24; i++) expect(fb.indices[8 * 320 + 4 + i]).toBe(0xff)
  })

  it('missing glyph between known letters uses tofu and advances by 16 pixels', () => {
    const fb = createFramebuffer()
    fb.indices.fill(77)
    expect(renderText(fb, 'A乙A', 4, 8, 0x22, mockGlyphs)).toBe(32)
    expect(fb.indices[8 * 320 + 4]).toBe(0x22)
    expect(fb.indices[8 * 320 + 12]).toBe(0x22)
    expect(fb.indices[8 * 320 + 27]).toBe(77)
    expect(fb.indices[8 * 320 + 28]).toBe(0x22)
    expect(fb.indices[8 * 320 + 36]).toBe(77)
  })
})

// ── measureText ───────────────────────────────────────────────────────

describe('measureText (P4.T3)', () => {
  it('8 for A', () => {
    expect(measureText('A', mockGlyphs)).toBe(8)
  })

  it('16 for 中', () => {
    expect(measureText('中', mockGlyphs)).toBe(16)
  })

  it('24 for A中', () => {
    expect(measureText('A中', mockGlyphs)).toBe(24)
  })

  it('unknown char defaults to 16', () => {
    expect(measureText('\u0000', mockGlyphs)).toBe(16)
  })

  it('empty string → 0', () => {
    expect(measureText('', mockGlyphs)).toBe(0)
  })
})

